  function characterData(){return {...loadedData,name,player,deity,deityPower,ancestry,characterClass,origin,originBenefits,amnesicSkill,amnesicPower,trainedSkills,knowledgeSkills,skillAttributes,level,baseAttributes,ancestryChoices,hpAdjustment,maximumHp,currentHp,currentMp,temporaryHp,temporaryMp,attacks,equipment,powers,spells,notes,diary,temporaryAttributes,defenseBase,defenseUsesAttribute,defenseAttribute,defenseManual,manualRd,movementBase,otherMovement,sizeOverride,golemElement,golemPower,proficiencyAdds,proficiencyRemoves,proficiencyChoice,coins,activeConditionNames,effects};}
  async function save(){
    if(!Number.isInteger(level)||level<1||level>20){startupError='O nível deve ser um número inteiro entre 1 e 20.';return;}
    const purchaseError=attributePurchaseError(baseAttributes);if(purchaseError){startupError=purchaseError;return;}
    if(carried>loadLimit*2){startupError='Carga acima do dobro do limite. Remova itens antes de salvar.';return;}
    if(roomSheetId){const data=characterData();if(sendRoom({type:'save_sheet',id:roomSheetId,baseRevision:roomSheetRevision,data}))submittedSheet=JSON.stringify(data);return;}
    const data=characterData(),snapshot=JSON.stringify(data);
    if(desktopAvailable){try{const item=await invoke<LocalCharacter>('save_character',{id:currentLocalId||null,data});currentLocalId=item.id;savedCharacters=[item,...savedCharacters.filter(c=>c.id!==item.id)];hasCharacter=true;if(snapshot===JSON.stringify(characterData()))sheetDirty=false;startupError='';}catch(error){startupError=`Não foi possível salvar: ${error}`;}}
    else{try{localStorage.setItem('tormenta-vtt-character',snapshot);hasCharacter=true;sheetDirty=false;startupError='';}catch{startupError='Não foi possível salvar no navegador. Seu rascunho foi preservado.';}}
  }
  function openLocal(item:LocalCharacter){currentLocalId=item.id;roomSheetId='';restore(item.data);sheetOpen=true;section='fichas';sheetDirty=false;}
  async function deleteLocal(item:LocalCharacter){
    if(!confirm(`Apagar a ficha local “${item.name}” permanentemente? A cópia da mesa não será apagada e poderá ser sincronizada novamente ao reconectar.`))return;
    try{await invoke('delete_character',{id:item.id});savedCharacters=savedCharacters.filter(c=>c.id!==item.id);hasCharacter=savedCharacters.length>0;if(currentLocalId===item.id)currentLocalId='';startupError='';}
    catch(error){startupError=`Não foi possível apagar a ficha: ${error}`;}
  }
  async function deleteSavedRoom(item:RoomCard){
    if(!confirm(`Apagar a mesa “${item.name}” permanentemente? Mapas, tokens, músicas compartilhadas, chat, participantes e fichas desta mesa serão excluídos. Suas fichas locais e biblioteca pessoal serão preservadas.`))return;
    try{const remaining=await invoke<number>('delete_room',{roomId:item.id});savedRooms=savedRooms.filter(r=>r.id!==item.id);startupError=remaining?`Mesa apagada, mas ${remaining} arquivo(s) não puderam ser removidos do armazenamento.`:'';}
    catch(error){startupError=`Não foi possível apagar a mesa: ${error}`;}
  }
  function openRoomSheet(item:RoomCharacter){roomSheetId=item.id;roomSheetRevision=item.revision;restore(item.data);sheetOpen=true;section='mesas';sheetDirty=false;clearConflict();}
  function createAdvanced(){loadedData={};currentLocalId='';roomSheetId='';name='';player='';deity='';deityPower='';ancestry='';characterClass='';origin='';originBenefits=[];amnesicSkill='';amnesicPower='';trainedSkills=[];knowledgeSkills=[];skillAttributes={};level=1;baseAttributes=[0,0,0,0,0,0];ancestryChoices=[];hpAdjustment=0;currentHp=0;currentMp=0;temporaryHp=0;temporaryMp=0;attacks=[];equipment=[];powers=[];spells=[];notes='';diary='';temporaryAttributes=[0,0,0,0,0,0];defenseBase=10;defenseUsesAttribute=true;defenseAttribute=1;defenseManual=0;manualRd={};movementBase=null;otherMovement={};sizeOverride=null;golemElement='';golemPower='';proficiencyAdds=[];proficiencyRemoves=[];proficiencyChoice='Armas marciais';coins={to:0,ts:0,tc:0};activeConditionNames=[];effects=[];choiceEditor='';newDialog=false;sheetOpen=true;sheetDirty=false;}
  function hpFor(atLevel:number){if(!classRule)return Math.max(0,hpAdjustment);const hpAttribute=deityPower==='Dom da Esperança'?attributes[4]:attributes[2];return Math.max(0,classRule.hp+hpAttribute+(atLevel-1)*Math.max(1,classRule.hpLevel+hpAttribute)+(ancestryRule?.hpStart??0)+(ancestryRule?.hpLevel??0)*atLevel+(selectedPowers.includes('Vitalidade')?atLevel:0)+hpAdjustment);}
  function mpFor(atLevel:number){return classRule?Math.max(0,classRule.mp*atLevel+(classRule.mana===undefined?0:attributes[classRule.mana])+(deityPower==='Bênção do Mana'?Math.ceil(atLevel/2):0)+(selectedPowers.includes('Vontade de Ferro')?Math.floor(atLevel/2):0)+(selectedPowers.includes('Coração Heroico')?3*(1+Number(atLevel>=5)+Number(atLevel>=11)+Number(atLevel>=17)):0)):0;}
  function updateResources(change:()=>void){const oldHp=maximumHp,oldMp=maximumMp;change();const newHp=hpFor(level)+activeEffects.filter(e=>e.kind==='PV máximo').reduce((n,e)=>n+e.value,0),newMp=mpFor(level)+activeEffects.filter(e=>e.kind==='PM máximo').reduce((n,e)=>n+e.value,0);currentHp=currentHp===oldHp?newHp:Math.min(currentHp,newHp);currentMp=currentMp===oldMp?newMp:Math.min(currentMp,newMp);}
  function changeLevel(value:number,input:HTMLInputElement){if(!Number.isInteger(value)||value<1||value>20){input.value=String(level);startupError='O nível deve ser um número inteiro entre 1 e 20.';return;}updateResources(()=>level=value);sheetDirty=true;startupError='';}
  function closeSheet(destination:Section=roomSheetId?'mesas':'fichas'){if(sheetOpen&&sheetDirty&&!confirm('Há alterações não salvas ou aguardando revisão. Sair sem salvar este rascunho?'))return;sheetOpen=false;compendiumOpen=false;section=destination;startupError='';}
  function changeMaximumHp(value:number){if(!Number.isFinite(value)||value<0)return;const wasFull=currentHp===maximumHp;hpAdjustment+=Math.trunc(value)-maximumHp;if(wasFull)currentHp=Math.trunc(value);}
  function selectDeity(value:string){updateResources(()=>{deity=value;deityPower='';knowledgeSkills=[];});choiceEditor=value?'devotion':'';}
  function selectPower(value:string){updateResources(()=>{deityPower=value;knowledgeSkills=[];});choiceEditor=value==='Conhecimento Enciclopédico'?'devotion':'';}
  function selectOrigin(value:string){if(ancestry==='Golem')return;updateResources(()=>{origin=value;originBenefits=[];amnesicSkill='';amnesicPower='';});choiceEditor=value?'origin':'';}
  function toggleOriginBenefit(value:string){updateResources(()=>{if(originBenefits.includes(value))originBenefits=originBenefits.filter(x=>x!==value);else if(originBenefits.length<2)originBenefits=[...originBenefits,value];});if(originBenefits.length===2)choiceEditor='';}
  function changeAttribute(index:number,value:number,input:HTMLInputElement){if(!canChangeAttribute(baseAttributes,index,value)){input.value=String(baseAttributes[index]);startupError='A compra de atributos permite 10 pontos no total; valores 3 e 4 custam 4 e 7 pontos.';return;}updateResources(()=>baseAttributes[index]=value);sheetDirty=true;startupError='';}
  function selectClass(value:string){updateResources(()=>characterClass=value);}
  function toggleTrainedSkill(value:string){trainedSkills=trainedSkills.includes(value)?trainedSkills.filter(x=>x!==value):[...trainedSkills,value];}
  function toggleKnowledgeSkill(value:string){if(knowledgeSkills.includes(value))knowledgeSkills=knowledgeSkills.filter(x=>x!==value);else if(knowledgeSkills.length<2)knowledgeSkills=[...knowledgeSkills,value];if(knowledgeSkills.length===2)choiceEditor='';}
  function skillAttribute(name:string,attribute:number){const choice=skillAttributes[name];if(Number.isInteger(choice)&&choice>=0&&choice<labels.length)return choice;return name==='Adestramento'&&deityPower==='Compreender os Ermos'?4:name==='Guerra'&&deityPower==='Fé Guerreira'?4:name==='Atletismo'&&selectedPowers.includes('Acrobático')?1:attribute;}
  function selectSkillAttribute(name:string,value:number){if(Number.isInteger(value)&&value>=0&&value<labels.length)skillAttributes={...skillAttributes,[name]:value};}
  function skillValue(skill:{name:string;attribute:number}){const attribute=skillAttribute(skill.name,skill.attribute);return skillTotal(level,effectiveAttributes[attribute],trainedSkills.includes(skill.name)||automaticSkills.includes(skill.name)||trainedByPower.includes(skill.name),skillBonus(skill.name,attribute));}
  function skillBonus(name:string,attribute:number){const physical=attribute<=2,mental=attribute>=3;const nonProficient=!!(equippedArmor&&!(equippedArmor.heavy?proficiencies.includes('Armaduras pesadas'):proficiencies.includes('Armaduras leves'))||equippedShield&&!proficiencies.includes('Escudos'));return (grantedSkillBonuses[deityPower]?.[name]??0)+(selectedPowers.includes('Vontade de Ferro')&&name==='Vontade'?2:0)+(selectedPowers.includes('Vitalidade')&&name==='Fortitude'?2:0)+(selectedPowers.includes('Atlético')&&name==='Atletismo'?2:0)+(selectedPowers.includes('Investigador')&&name==='Investigação'?2:0)+(selectedPowers.includes('Investigador')&&name==='Intuição'?effectiveAttributes[3]:0)+(selectedPowers.includes('Sentidos Aguçados')&&name==='Percepção'?2:0)+(selectedPowers.includes('Dom Artístico')&&name==='Atuação'?2:0)+(selectedPowers.includes('Esse Cheiro...')&&name==='Fortitude'?2:0)+(deity==='Nimb'&&attribute===5?-5:0)+(name==='Furtividade'?sizeModifiers(currentSize)[0]:0)+(name==='Iniciativa'?conditionPenalty(activeStatuses,'initiative'):0)+(name==='Percepção'?conditionPenalty(activeStatuses,'perception'):0)+(name==='Reflexos'?conditionPenalty(activeStatuses,'reflex'):0)+Math.min(conditionPenalty(activeStatuses,'skill'),physical?conditionPenalty(activeStatuses,'physical'):mental?conditionPenalty(activeStatuses,'mental'):0)+((nonProficient&&attribute<=1)||['Acrobacia','Furtividade','Ladinagem'].includes(name)?armorPenalty:0)+activeEffects.filter(e=>e.kind==='Perícia todas'||e.kind==='Perícia'&&e.skill===name).reduce((n,e)=>n+e.value,0);}
  function selectAncestry(value:string){updateResources(()=>{ancestry=value;ancestryChoices=[];sizeOverride=null;movementBase=null;otherMovement=value==='Sereia/Tritão'?{Natação:12}:value==='Sílfide'?{Voo:12}:{};if(value==='Golem'){origin='';originBenefits=[];}else{golemElement='';golemPower='';}});choiceEditor=value==='Golem'?'golem':ancestries[value]?.choices?'ancestry':'';}
  function toggleChoice(index:number){updateResources(()=>{if(ancestryChoices.includes(index))ancestryChoices=ancestryChoices.filter(i=>i!==index);else if(ancestryChoices.length<(ancestryRule?.choices??0)&&!ancestryRule?.forbidden?.includes(index))ancestryChoices=[...ancestryChoices,index];});if(ancestryChoices.length===ancestryRule?.choices)choiceEditor='';}
  function finishAmnesic(){if(amnesicSkill&&amnesicPower)choiceEditor='';}
  function finishGolem(){if(golemElement&&golemPower)choiceEditor='';}
  function autoGrow(event:Event){const element=event.currentTarget as HTMLTextAreaElement;element.style.height='auto';element.style.height=`${element.scrollHeight}px`;sheetDirty=true;}
  function addBlank(kind:string,circle=1){addEntry({name:'',kind,description:'',circle});}
  function addEntry(source:Record<string,any>){const entry={...source,id:nextId++,open:false} as Entry;if(entry.kind==='Equipamento'&&itemSpaces([...equipment,entry],coins)>loadLimit*2){startupError='Carga acima do dobro do limite. O item não foi adicionado.';return;}sheetDirty=true;if(entry.kind==='Ataque')attacks.push(entry);else if(entry.kind==='Equipamento')equipment.push(entry);else if(entry.kind==='Poder')powers.push(entry);else spells.push(entry);}
  function setItemLoad(item:Entry,field:'spaces'|'quantity',value:number,input:HTMLInputElement){const old=item[field];item[field]=value;if(!Number.isFinite(value)||value<0||itemSpaces(equipment,coins)>loadLimit*2){item[field]=old;startupError='Carga acima do dobro do limite. A alteração foi desfeita.';}else sheetDirty=true;input.value=String(item[field]??(field==='quantity'?1:0));}
  function setCoins(kind:'to'|'ts'|'tc',value:number,input:HTMLInputElement){const old=coins[kind];coins[kind]=value;if(!Number.isInteger(value)||value<0||itemSpaces(equipment,coins)>loadLimit*2){coins[kind]=old;startupError='Carga acima do dobro do limite. A alteração foi desfeita.';}else sheetDirty=true;input.value=String(coins[kind]);}
  function changeCatalogGroup(value:CatalogGroup|'Todos'){catalogGroup=value;categoryFilter='Todas';circleFilter='Todos';traditionFilter='Todas';}
  function openCatalog(group:CatalogGroup, proficient=false){changeCatalogGroup(group);catalogOnlyProficient=proficient;compendiumOpen=true;editor='';}
  function catalogEntry(item:CatalogItem, asEquipment=false):Record<string,any>{
    const source=`Livro Básico, ${item.page}`;
    if(item.group==='Magias'){
      return {name:item.name,kind:'Magia',circle:item.circle,magicType:item.tradition,activation:item.execution,range:item.range,duration:item.duration,cost:item.cost,resistance:item.resistance,source,description:[item.detail,`Resistência: ${item.resistance}`,item.enhancements,source].filter(Boolean).join(' · ')};
    }else if(item.group==='Poderes'){
      return {name:item.name,kind:'Poder',source,description:`${item.detail} · ${source}`};
    }else if(item.group==='Armas'&&!asEquipment){
      return {name:item.name,kind:'Ataque',damage:item.damage,critical:item.critical,damageType:item.damageType,range:item.range==='—'?'Corpo a corpo':item.range,source,category:item.category,skill:item.range==='—'?'Luta':'Pontaria',damageAttribute:item.range==='—'?0:-1,linked:true,description:`${item.category} · ${item.detail} · ${source}`};
    }else{
      const itemType=item.group==='Armas'?'Arma':item.group==='Escudos'?'Escudo':item.group==='Armaduras'?'Armadura':'Consumível';
      return {name:item.group==='Munições'?`${item.name} (${item.quantity})`:item.name,kind:'Equipamento',itemType,quantity:1,spaces:item.spaces,price:item.price,source,defense:signed(item.defense),penalty:signed(item.penalty),heavy:item.category==='Pesada',description:`${item.group==='Armas'?`${item.damage} · ${item.critical} · ${item.damageType} · ${item.range}`:item.group==='Munições'?`Pacote com ${item.quantity} unidades.`:`Defesa ${item.defense} · penalidade ${item.penalty}`} · ${source}`};
    }
  }
  function addCatalogItem(item:CatalogItem, asEquipment=false){addEntry(catalogEntry(item,asEquipment));}
  function removeEntry(list:Entry[],id:number){sheetDirty=true;const i=list.findIndex(x=>x.id===id);if(i>=0)list.splice(i,1);}
  function drop(kind:string,event:DragEvent){event.preventDefault();const raw=event.dataTransfer?.getData('application/json');if(!raw)return;try{const item=JSON.parse(raw);if(item?.kind===kind&&typeof item.name==='string')addEntry(item);}catch{/* Ignora dados arrastados de fora do compêndio. */}}
  function dragCatalogItem(item:CatalogItem,event:DragEvent){event.dataTransfer?.setData('application/json',JSON.stringify(catalogEntry(item)));}
</script>

<svelte:head><meta name="color-scheme" content="light dark" /></svelte:head>
<svelte:window onkeydown={event=>{if(event.key!=='Escape')return;if(effectEditor)closeEffectEditor();else if(editor)closeEditor();else if(settingsOpen)closeSettings();else if(newDialog)closeNewDialog();else if(compendiumOpen)compendiumOpen=false;else if(roomSheetOverlay)closeSheet();}}/>
<div class={`app-shell${sheetOpen&&compendiumOpen?' with-compendium':''}${roomSheetOverlay?' room-sheet-open':''}`}>
  {#if !sheetOpen}<header class="app-header" inert={roomSheetOverlay||newDialog||settingsOpen}><button class="brand" onclick={()=>closeSheet(startPage)} aria-label="Início"><span class="brand-sigil"><Icon name="sword"/></span><strong>A Guilda VTT</strong></button><nav class="global-nav" aria-label="Áreas do aplicativo">{#each [['resumo','home','Resumo'],['mesas','table','Mesas'],['fichas','users','Fichas'],['livros','book','Livros']] as tab}<button class:active={section===tab[0]} aria-current={section===tab[0]?'page':undefined} title={tab[2]} onclick={()=>navigate(tab[0] as Section)}><Icon name={tab[1]} size={16}/>{tab[2]}</button>{/each}</nav><div class="app-actions"><button class="icon-button" onclick={openSettings} aria-label="Configurações"><Icon name="settings"/></button></div></header>{/if}
  {#if !sheetOpen || roomSheetOverlay}
    <main class:room-hub={section==='mesas'} class="hub" inert={roomSheetOverlay||newDialog||settingsOpen}>
      <section class="hub-content" bind:this={hubContent}><div class="hub-heading"><h1>{section==='resumo'?'Resumo':section==='mesas'?'Mesas':section==='fichas'?'Fichas':'Livros'}</h1>{#if section==='fichas'&&sheetTab==='jogador'}<button class="primary" onclick={openNewDialog}><Icon name="plus" size={16}/>Nova ficha</button>{/if}</div>
        {#if startupError}<p class="mesa-error" role="alert">{startupError}</p>{/if}
        {#if section==='resumo'}
          <section class="summary-hero" aria-label="Bem-vindo à Guilda"><h2>Histórias começam à mesa.</h2><p>Prepare sua campanha, reúna os jogadores e continue sua aventura.</p></section>
          <div class="summary-actions"><button class="primary" onclick={()=>navigate('mesas')}><Icon name="table"/>Entrar em uma mesa</button><button onclick={openNewDialog}><Icon name="plus"/>Nova ficha</button></div>
          <section class="summary-section"><header><h2>Mesas recentes</h2><button onclick={()=>navigate('mesas')}>Ver todas</button></header>{#if savedRooms.length}<div class="summary-list">{#each savedRooms.slice(0,3) as item}<button onclick={()=>navigate('mesas')}><span class="summary-cover">{#if item.coverUrl}<img src={item.coverUrl} alt=""/>{:else}{item.name.slice(0,2).toUpperCase()}{/if}</span><span><strong>{item.name}</strong><small>{item.role==='master'?'Mestre':'Jogador'}</small></span><Icon name="chevron"/></button>{/each}</div>{:else}<p class="summary-empty">Suas mesas recentes aparecerão aqui.</p>{/if}</section>
          <section class="summary-section"><header><h2>Fichas recentes</h2><button onclick={()=>navigate('fichas')}>Ver todas</button></header>{#if savedCharacters.length}<div class="summary-list">{#each savedCharacters.slice(0,3) as item}<button onclick={()=>openLocal(item)}><span class="card-icon"><Icon name="users"/></span><span><strong>{item.name}</strong><small>{[item.data.ancestry,item.data.characterClass].filter(Boolean).join(' · ')||'Ficha avançada'}</small></span><Icon name="chevron"/></button>{/each}</div>{:else}<p class="summary-empty">Crie uma ficha para começar sua aventura.</p>{/if}</section>
        {:else if section==='mesas'}<Mesa characters={savedCharacters} rooms={savedRooms} onOpen={openRoomSheet} onNew={createAdvanced} onDeleteRoom={deleteSavedRoom} onRoomsChanged={refreshRooms} onSettings={openSettings} {confirmLeave}/>
        {:else if section==='fichas'}
          <nav class="sub-tabs" aria-label="Tipos de ficha"><button class:active={sheetTab==='jogador'} onclick={()=>sheetTab='jogador'}>Jogador</button><button class:active={sheetTab==='mestre'} onclick={()=>sheetTab='mestre'}>Mestre</button></nav>
          {#if sheetTab==='jogador' && (savedCharacters.length || hasCharacter)}
          {#if desktopAvailable}{#each savedCharacters as item}<div class="character-card-row"><button class="character-card" onclick={()=>openLocal(item)}><span class="card-icon"><Icon name="users"/></span><span><strong>{item.name}</strong><small>{[item.data.ancestry,item.data.characterClass&&`${item.data.characterClass} ${item.data.level}`].filter(Boolean).join(' · ')||'Ficha avançada'}</small></span><Icon name="chevron"/></button><button class="icon-button mesa-danger character-delete" aria-label={`Apagar ficha ${item.name}`} title="Apagar ficha" onclick={()=>deleteLocal(item)}><Icon name="trash"/></button></div>{/each}
          {:else}<button class="character-card" onclick={()=>sheetOpen=true}><span class="card-icon"><Icon name="users"/></span><span><strong>{name||'Personagem sem nome'}</strong><small>{[ancestry,characterClass&&`${characterClass} ${level}`].filter(Boolean).join(' · ')||'Ficha avançada'}</small></span><Icon name="chevron"/></button>{/if}
          {:else if sheetTab==='jogador'}<div class="empty-state"><Icon name="users" size={34}/><strong>Nenhuma ficha de jogador</strong><span>Crie sua primeira ficha para começar.</span></div>
          {:else}<div class="master-sheet-types"><article><Icon name="person" size={24}/><h2>NPCs</h2><p>Personagens recorrentes, aliados e figuras da campanha.</p><span>Em breve</span></article><article><Icon name="skull" size={24}/><h2>Ameaças</h2><p>Inimigos e criaturas preparados para encontros.</p><span>Em breve</span></article><article><Icon name="handshake" size={24}/><h2>Parceiros</h2><p>Aliados com benefícios próprios de Tormenta20.</p><span>Em breve</span></article></div>{/if}
        {:else}<div class="empty-state"><Icon name="book" size={34}/><strong>Nenhum livro adicionado</strong><span>Sua biblioteca de referência aparecerá aqui.</span></div>{/if}
      </section></main>
  {/if}
  {#if sheetOpen}
    {#if roomSheetOverlay}<button class="mesa-sheet-backdrop" aria-label="Fechar ficha" onclick={()=>closeSheet()}></button>{/if}
    <main class="sheet-page" class:mesa-sheet-overlay={roomSheetOverlay} inert={!!editor||effectEditor||settingsOpen} role={roomSheetOverlay?'dialog':undefined} aria-modal={roomSheetOverlay?'true':undefined} aria-label={roomSheetOverlay?'Ficha da mesa':undefined} tabindex="-1" bind:this={roomSheetDialog}><header class="sheet-toolbar"><button class="back-button" onclick={()=>closeSheet()}><Icon name="back"/>{section==='mesas'?'Mesa':'Fichas'}</button><div class="sheet-toolbar-context"><strong>{name||'Nova ficha'}</strong><small>{roomSheetId?`Mesa · revisão ${roomSheetRevision}`:sheetDirty?'Alterações não salvas':'Ficha local'}</small></div>{#if compendiumOpen&&catalogGroup==='Armas'}<label class="toolbar-filter"><input type="checkbox" bind:checked={catalogOnlyProficient}/> Só armas proficientes</label>{/if}<button aria-expanded={compendiumOpen} aria-controls="compendium-helper" onclick={()=>compendiumOpen=!compendiumOpen}><Icon name="book"/>Compêndio</button><button aria-label="Configurações" title="Configurações" onclick={openSettings}><Icon name="settings"/></button><button class="primary" disabled={!!roomSheetId&&!!$room.conflict} onclick={save}><Icon name="save"/>Salvar</button></header>
      {#if startupError}<p class="mesa-error" role="alert">{startupError}</p>{/if}
      {#if roomSheetId && $room.conflict}<div class="sheet-conflict" role="alert">A ficha mudou na mesa. Seu rascunho não foi sobrescrito. Copie o que precisar antes de carregar a versão atual. <button onclick={()=>{restore($room.conflict!.data);roomSheetRevision=$room.conflict!.revision;sheetDirty=false;clearConflict();}}>Carregar versão da mesa</button></div>{/if}
      {#if roomSheetId && $room.role==='player'}<p role="status">Alterações de atributos, perícias, poderes, magias e recursos são propostas ao mestre ao salvar. Até a aprovação, os cálculos desta edição são uma prévia; a ficha da mesa permanece inalterada.</p>{/if}
      {#if roomSheetId && $room.message}<p role="status">{$room.message}</p>{/if}
      {#if roomSheetId && sheetDirty && !$room.conflict && ($room.characters.find(c=>c.id===roomSheetId)?.revision??0)>roomSheetRevision}<div class="sheet-conflict" role="status">A ficha mudou na mesa enquanto você editava. Seu rascunho foi preservado; ao salvar, você poderá comparar as versões.</div>{/if}
      <div class="sheet" oninput={()=>sheetDirty=true} onchange={()=>sheetDirty=true}><section class="identity frame"><label class="name-field">Nome do personagem<input bind:value={name} placeholder="Nome"/></label><label>Jogador<input bind:value={player}/></label><label>Divindade<select value={deity} onchange={e=>selectDeity(e.currentTarget.value)}><option value="">Nenhuma</option>{#each Object.keys(deities) as item}<option>{item}</option>{/each}</select></label><label>Raça<select value={ancestry} onchange={e=>selectAncestry(e.currentTarget.value)}><option value="">Escolha</option>{#each Object.keys(ancestries) as item}<option>{item}</option>{/each}</select></label><label>Origem<select value={origin} disabled={ancestry==='Golem'} onchange={e=>selectOrigin(e.currentTarget.value)}><option value="">{ancestry==='Golem'?'Golem não escolhe origem':'Escolha'}</option>{#each Object.keys(origins) as item}<option>{item}</option>{/each}</select></label><label>Classe<select value={characterClass} onchange={e=>selectClass(e.currentTarget.value)}><option value="">Escolha</option>{#each Object.keys(classes) as item}<option>{item}</option>{/each}</select></label><label class="level-field">Nível<input type="number" min="1" max="20" value={level} oninput={e=>changeLevel(e.currentTarget.valueAsNumber,e.currentTarget)}/></label>
        {#if chosenDeity&&(!deityComplete||choiceEditor==='devotion') || chosenOrigin&&(!originComplete||choiceEditor==='origin')}<div class="background-rules">
          {#if chosenDeity&&(!deityComplete||choiceEditor==='devotion')}<div><h2>Devoção · {deity}</h2><p>{chosenDeity.restriction}</p><label>Poder concedido<select value={deityPower} onchange={e=>selectPower(e.currentTarget.value)}><option value="">Escolha um poder</option>{#each chosenDeity.powers as power}<option disabled={(power==='Dom da Imortalidade'&&characterClass!=='Paladino')||(power==='Dom da Ressurreição'&&characterClass!=='Clérigo')}>{power}</option>{/each}</select></label>{#if deityPower==='Conhecimento Enciclopédico'}<div class="benefit-options"><small>Escolha duas perícias de Inteligência ({knowledgeSkills.length}/2)</small>{#each skills.filter(s=>s.attribute===3) as skill}<label><input type="checkbox" checked={knowledgeSkills.includes(skill.name)} disabled={knowledgeSkills.length>=2&&!knowledgeSkills.includes(skill.name)} onchange={()=>toggleKnowledgeSkill(skill.name)}/>{skill.name}</label>{/each}</div>{/if}</div>{/if}
          {#if chosenOrigin&&(!originComplete||choiceEditor==='origin')}<div><h2>Origem · {origin}</h2>{#if origin==='Amnésico'}<p>O mestre escolhe uma perícia e um poder. Lembranças Graduais é recebido adicionalmente.</p><label>Perícia escolhida<select bind:value={amnesicSkill} onchange={finishAmnesic}><option value="">Escolha</option>{#each skills as skill}<option>{skill.name}</option>{/each}</select></label><label>Poder escolhido<input bind:value={amnesicPower} oninput={finishAmnesic} placeholder="Definido pelo mestre"/></label>{:else}<p>Escolha dois benefícios ({originBenefits.length}/2).</p><div class="benefit-options">{#each chosenOrigin.skills as skill}<label><input type="checkbox" checked={originBenefits.includes(`skill:${skill}`)} disabled={originBenefits.length>=2&&!originBenefits.includes(`skill:${skill}`)} onchange={()=>toggleOriginBenefit(`skill:${skill}`)}/>{skill} <small>perícia</small></label>{/each}{#each chosenOrigin.powers as power}<label><input type="checkbox" checked={originBenefits.includes(`power:${power}`)} disabled={originBenefits.length>=2&&!originBenefits.includes(`power:${power}`)} onchange={()=>toggleOriginBenefit(`power:${power}`)}/>{power} <small>poder</small></label>{/each}</div>{/if}</div>{/if}
        </div>{/if}{#if ancestry==='Golem'&&(!golemComplete||choiceEditor==='golem')}<div class="background-rules"><div><h2>Fonte elemental</h2><p>Imune ao tipo escolhido; dano mágico correspondente cura metade dos PV.</p><label>Elemento<select bind:value={golemElement} onchange={finishGolem}><option value="">Escolha</option><option>Água</option><option>Ar</option><option>Fogo</option><option>Terra</option></select></label></div><div><h2>Propósito de criação</h2><p>Sem origem; escolha um poder geral.</p><label>Poder<input bind:value={golemPower} oninput={finishGolem} placeholder="Poder geral"/></label></div></div>{/if}</section>
        {#if ancestryRule?.choices&&(!ancestryComplete||choiceEditor==='ancestry')}<section class="choice-strip frame"><strong>Escolha {ancestryRule.choices} atributos da raça</strong>{#each labels as label,index}<label class:disabled={ancestryRule.forbidden?.includes(index)}><input type="checkbox" checked={ancestryChoices.includes(index)} disabled={ancestryRule.forbidden?.includes(index)} onchange={()=>toggleChoice(index)}/>{label}</label>{/each}</section>{/if}
        <section class="attributes frame" aria-label="Atributos"><header><h2>Atributos</h2><div>{#if ancestryRule?.choices&&ancestryComplete}<button class="source-change" onclick={()=>choiceEditor='ancestry'}><Icon name="person" size={14}/>Alterar raça</button>{/if}<button class="stat-edit" aria-label="Modificar atributos" title="Modificadores temporários" onclick={()=>openEditor('attributes')}><Icon name="tune" size={14}/></button></div></header><p aria-live="polite">Compra: {attributeCost(baseAttributes)??'inválida'} / 10 pontos · antes dos bônus de raça e efeitos.</p>{#if attributePurchaseError(baseAttributes)}<p role="alert">{attributePurchaseError(baseAttributes)}</p>{/if}<div class="attributes-grid">{#each labels as label,index}<div class="attribute">{#if ancestryChoices.includes(index)}<span class="source-chip" title={`Atributo concedido por ${ancestry}`}><Icon name="person" size={12}/>Raça</span>{/if}<div class="attribute-hex"><span>{label}</span><strong>{effectiveAttributes[index]>=0?'+':''}{effectiveAttributes[index]}</strong></div><label>Base <input aria-label={`Base ${label}`} type="number" min="-1" max="4" value={baseAttributes[index]} oninput={e=>changeAttribute(index,e.currentTarget.valueAsNumber,e.currentTarget)}/></label></div>{/each}</div></section>
        <section class="resources"><div class="resource frame"><h2><Icon name="heart"/>Pontos de Vida</h2><label>Máximo<input aria-label="PV máximo (ajuste manual)" type="number" min="0" value={maximumHp} oninput={e=>e.currentTarget.value&&changeMaximumHp(Number(e.currentTarget.value))}/></label><label>Atual<input type="number" bind:value={currentHp}/></label><label>Temporários<input type="number" bind:value={temporaryHp}/></label></div><div class="resource frame"><h2><Icon name="spark"/>Pontos de Mana</h2><label>Máximo<input readonly value={maximumMp}/></label><label>Atual<input type="number" bind:value={currentMp}/></label><label>Temporários<input type="number" bind:value={temporaryMp}/></label></div><div class="resource-stat frame"><button class="stat-edit" aria-label="Editar Defesa" onclick={()=>openEditor('defense')}><Icon name="tune" size={14}/></button><h2>Defesa {#if defenseBase!==10||!defenseUsesAttribute||defenseAttribute!==1||defenseManual!==0}<small>· Editado</small>{/if}</h2><strong>{defense}</strong><small>RD {rdGeneral}</small></div><div class="resource-stat frame"><button class="stat-edit" aria-label="Editar deslocamento e tamanho" onclick={()=>openEditor('movement')}><Icon name="tune" size={14}/></button><h2>Deslocamento</h2><strong>{movement}<small>m</small></strong><small>{currentSize}{#if overloaded} · Sobrecarregado{/if}</small></div></section>
        <section class="conditions-panel frame"><header><h2>Condições</h2><small>{activeStatuses.length} ativa(s)</small></header><details><summary>Adicionar ou remover condições</summary><div class="condition-picks">{#each conditions as condition}<label title={condition.note}><input type="checkbox" checked={activeConditionNames.includes(condition.name)} disabled={ancestry==='Golem'&&!!condition.group} onchange={()=>toggleCondition(condition.name)}/>{condition.name}</label>{/each}</div></details>{#each activeStatuses as condition}<small>{condition.name}: {condition.note}</small>{/each}</section>
        <div class="sheet-columns"><div class="sheet-main">
          <section class="sheet-panel frame" aria-label="Ataques" ondragover={e=>e.preventDefault()} ondrop={e=>drop('Ataque',e)}><header><h2><Icon name="sword"/>Ataques</h2><div class="header-actions"><button aria-label="Escolher arma no compêndio" title="Armas do compêndio" onclick={()=>openCatalog('Armas',true)}><Icon name="book" size={16}/></button><button onclick={()=>addBlank('Ataque')}><Icon name="plus"/>Adicionar</button></div></header>{#each attacks as item}<div class="entry"><button class="entry-summary" onclick={()=>item.open=!item.open}><Icon name="dice"/><input bind:value={item.name} placeholder="Nome do ataque" onclick={e=>e.stopPropagation()}/><span>{item.linked?linkedAttack(item):item.attackBonus||'—'}</span><span>{item.linked?linkedDamage(item):item.damage||'—'}</span><Icon name="chevron"/></button>{#if item.open}<div class="entry-editor"><label><input type="checkbox" bind:checked={item.linked}/> Cálculo vinculado</label><label>Perícia utilizada<select bind:value={item.skill}><option>Luta</option><option>Pontaria</option></select></label><label>Categoria<select bind:value={item.category}><option>Simples</option><option>Marcial</option><option>Exótica</option><option>Fogo</option></select></label><label>Tipo de dano<input bind:value={item.damageType}/></label><label>Alcance<input bind:value={item.range}/></label><label>Atributo no dano<select bind:value={item.damageAttribute}><option value={-1}>Nenhum</option>{#each labels as label,index}<option value={index}>{label}</option>{/each}</select></label>{#if item.linked}<label>Bônus manual de ataque<input type="number" bind:value={item.manualAttack}/></label><label><input type="checkbox" checked={!!item.manoeuvre} onchange={e=>item.manoeuvre=e.currentTarget.checked}/> Manobra</label>{:else}<label>Bônus de ataque preservado<input bind:value={item.attackBonus}/></label>{/if}<label>Dano da arma<input bind:value={item.damage}/></label><label>Bônus manual de dano<input type="number" bind:value={item.manualDamage}/></label><label>Crítico<input bind:value={item.critical}/></label><label class="wide">Descrição / macros<textarea bind:value={item.description}></textarea></label><button class="icon-button danger entry-delete" aria-label={`Apagar ataque ${item.name||'sem nome'}`} title="Apagar ataque" onclick={()=>removeEntry(attacks,item.id)}><Icon name="trash" size={16}/></button></div>{/if}</div>{/each}{#if !attacks.length}<p class="drop-hint">Arraste um ataque do compêndio ou adicione manualmente.</p>{/if}</section>
          <section class="sheet-panel frame" aria-label="Habilidades e poderes gerais" ondragover={e=>e.preventDefault()} ondrop={e=>drop('Poder',e)}><header><h2><Icon name="power"/>Habilidades e poderes gerais</h2><div class="header-actions">{#if chosenDeity&&deityComplete}<button class="source-change" onclick={()=>choiceEditor='devotion'}><Icon name="devotion" size={14}/>Alterar devoção</button>{/if}{#if (chosenOrigin&&originComplete)||ancestry==='Golem'&&golemComplete}<button class="source-change" onclick={()=>choiceEditor=ancestry==='Golem'?'golem':'origin'}><Icon name={ancestry==='Golem'?'person':'dna'} size={14}/>Alterar {ancestry==='Golem'?'raça':'origem'}</button>{/if}<button aria-label="Escolher poder no compêndio" title="Poderes e habilidades do compêndio" onclick={()=>openCatalog('Poderes')}><Icon name="book" size={16}/></button><button onclick={()=>addBlank('Poder')}><Icon name="plus"/>Adicionar</button></div></header>{#each selectedPowers as power}<div class="rule-power"><Icon name="power"/><div><strong>{power}</strong><span class="source-chip">{#if power===deityPower}<Icon name="devotion" size={12}/>Devoção{:else if ancestry==='Golem'&&power===golemPower}<Icon name="person" size={12}/>Raça{:else}<Icon name="dna" size={12}/>Origem{/if}</span>{#if powerNotes[power]}<span>{powerNotes[power]}</span>{/if}</div></div>{/each}{#each powers as item}<div class="entry"><button class="entry-summary simple" onclick={()=>item.open=!item.open}><Icon name="power"/><input bind:value={item.name} placeholder="Nome do poder" onclick={e=>e.stopPropagation()}/><Icon name="chevron"/></button>{#if item.open}<div class="entry-editor"><label>Execução<input bind:value={item.activation}/></label><label>PM<input bind:value={item.cost}/></label><label>Fonte<input bind:value={item.source}/></label><label class="wide">Descrição<textarea bind:value={item.description}></textarea></label><button class="danger" onclick={()=>removeEntry(powers,item.id)}>Remover</button></div>{/if}</div>{/each}</section>
          <section class="sheet-panel frame spells" aria-label="Magias" ondragover={e=>e.preventDefault()} ondrop={e=>drop('Magia',e)}>
            <header><h2><Icon name="spark"/>Magias</h2><button aria-label="Escolher magia no compêndio" title="Magias do compêndio" onclick={()=>openCatalog('Magias')}><Icon name="book" size={16}/></button></header>
            <div class="spell-circles">{#each [1,2,3,4,5] as circle}<section><header><strong>{circle}º Círculo</strong><span>{[1,3,6,10,15][circle-1]} PM</span></header>{#each spells.filter(s=>Number(s.circle)===circle) as item}<div class="entry"><div class="spell-row"><button class="entry-summary simple" onclick={()=>item.open=!item.open}><Icon name="spark"/><input bind:value={item.name} placeholder="Nome da magia" onclick={e=>e.stopPropagation()}/><Icon name="chevron"/></button>{#if String(item.duration||'').toLowerCase().includes('cena')||String(item.duration||'').toLowerCase().includes('sustentada')||String(item.duration||'').toLowerCase().includes('dia')}<button class:active={item.active} title="Gastar PM inicial para ativar; manutenção manual" onclick={()=>spellToggle(item)}>{item.active?'Ativa':'Ativar'}</button>{/if}</div>{#if item.open}<div class="entry-editor"><label>Tipo<select bind:value={item.magicType}><option>Arcana</option><option>Divina</option><option>Universal</option></select></label><label>Escola<input bind:value={item.school}/></label><label>Execução<input bind:value={item.activation}/></label><label>Alcance<input bind:value={item.range}/></label><label>Alvo/Área<input bind:value={item.target}/></label><label>Duração<input bind:value={item.duration}/></label><label>Custo<input bind:value={item.cost}/></label><label>Resistência<input bind:value={item.resistance}/></label><label class="wide">Descrição<textarea bind:value={item.description}></textarea></label><button class="danger" onclick={()=>removeEntry(spells,item.id)}>Remover</button></div>{/if}</div>{/each}<button class="circle-add" onclick={()=>addBlank('Magia',circle)}><Icon name="plus"/>Adicionar</button></section>{/each}</div>
          </section>
          <section class="sheet-panel frame"><header><h2><Icon name="tune"/>Efeitos personalizados</h2><button onclick={()=>editEffect()}><Icon name="plus"/>Adicionar</button></header>{#each effects as effect}<div class="effect-row"><div><strong>{effect.name}</strong><small>{effect.kind}{effect.kind==='Atributo'?` · ${labels[effect.attribute]}`:effect.kind==='Perícia'?` · ${effect.skill}`:''} {effect.value>=0?'+':''}{effect.value} · {effect.cost} PM</small>{#if effect.description}<small>{effect.description}</small>{/if}</div><button onclick={()=>effectToggle(effect)} aria-pressed={effect.active}>{effect.active?'Desativar':'Ativar'}</button><button onclick={()=>editEffect(effect)} aria-label={`Editar ${effect.name}`}><Icon name="tune" size={15}/></button></div>{/each}</section>
          <section class="notes frame"><h2>Anotações</h2><textarea bind:value={notes} oninput={autoGrow} placeholder="Notas rápidas da ficha..."></textarea></section><section class="notes frame diary"><h2>Diário</h2><textarea bind:value={diary} oninput={autoGrow} placeholder="Registre acontecimentos, pistas e objetivos..."></textarea></section>
        </div><aside class="sheet-side"><section class="skills-panel frame"><header><div><h2>Perícias</h2><small>Treino + atributo + metade do nível</small></div><div class="header-actions">{#if chosenOrigin&&originComplete}<button class="source-change" onclick={()=>choiceEditor='origin'}><Icon name="dna" size={14}/>Alterar origem</button>{/if}{#if deityPower==='Conhecimento Enciclopédico'&&deityComplete}<button class="source-change" onclick={()=>choiceEditor='devotion'}><Icon name="devotion" size={14}/>Alterar devoção</button>{/if}</div></header><div class="skills-grid">{#each skills as skill}{@const total = skillValue(skill)}<div class="skill-row"><label><input type="checkbox" aria-label={`Treinado em ${skill.name}`} checked={trainedSkills.includes(skill.name)||automaticSkills.includes(skill.name)||trainedByPower.includes(skill.name)} disabled={automaticSkills.includes(skill.name)||trainedByPower.includes(skill.name)} onchange={()=>toggleTrainedSkill(skill.name)}/><span>{skill.name}</span>{#if automaticSkills.includes(skill.name)}<span class="source-icon" title="Concedida pela origem"><Icon name="dna" size={13}/></span>{:else if trainedByPower.includes(skill.name)}<span class="source-icon" title="Concedida pela devoção"><Icon name="devotion" size={13}/></span>{/if}</label><select aria-label={`Atributo de ${skill.name}`} value={skillAttribute(skill.name,skill.attribute)} onchange={event=>selectSkillAttribute(skill.name,Number(event.currentTarget.value))}>{#each labels as label,index}<option value={index}>{label}</option>{/each}</select><strong>{total>=0?'+':''}{total}</strong></div>{/each}</div></section>
          <section class="sheet-panel frame" aria-label="Equipamentos" ondragover={e=>e.preventDefault()} ondrop={e=>drop('Equipamento',e)}><header><h2><Icon name="bag"/>Equipamentos</h2></header>
            {#each ['Arma','Armadura','Escudo','Itens gerais'] as group}
              <h3 class="equipment-group"><span>{group==='Arma'?'Armas':group==='Armadura'?'Armaduras':group==='Escudo'?'Escudos':group}</span><span class="equipment-group-actions">{#if group!=='Itens gerais'}<button aria-label={`Escolher ${group.toLowerCase()} no compêndio`} title="Abrir compêndio" onclick={()=>openCatalog(group==='Arma'?'Armas':group==='Armadura'?'Armaduras':'Escudos')}><Icon name="book" size={13}/></button>{/if}<button aria-label={`Adicionar ${group.toLowerCase()}`} title={`Adicionar ${group.toLowerCase()}`} onclick={()=>addEntry({name:'',kind:'Equipamento',description:'',itemType:group==='Itens gerais'?'Outro':group,quantity:1,spaces:0})}><Icon name="plus" size={13}/></button></span></h3>
              {#each equipment.filter(e=>group==='Itens gerais'?!['Arma','Armadura','Escudo'].includes(String(e.itemType)):e.itemType===group) as item}<div class="entry"><button class="entry-summary equipment-row" onclick={()=>item.open=!item.open}><input type="checkbox" checked={!!item.equipped} aria-label="Equipado" onchange={e=>{item.equipped=e.currentTarget.checked;}} onclick={e=>e.stopPropagation()}/><input type="number" min="0" value={Number(item.quantity??1)} onchange={e=>setItemLoad(item,'quantity',Number(e.currentTarget.value),e.currentTarget)} aria-label="Quantidade" onclick={e=>e.stopPropagation()}/><input bind:value={item.name} placeholder="Item" onclick={e=>e.stopPropagation()}/><span>{item.spaces??0}</span><Icon name="chevron"/></button>{#if item.open}<div class="entry-editor"><label>Tipo<select bind:value={item.itemType}><option>Arma</option><option>Armadura</option><option>Escudo</option><option>Consumível</option><option>Ferramenta</option><option>Outro</option></select></label><label>Espaços<input type="number" min="0" step="0.5" value={Number(item.spaces??0)} onchange={e=>setItemLoad(item,'spaces',Number(e.currentTarget.value),e.currentTarget)}/></label><label>Preço<input bind:value={item.price}/></label>{#if item.itemType==='Armadura'||item.itemType==='Escudo'}<label>Bônus de Defesa<input type="number" bind:value={item.defense}/></label><label>Penalidade<input type="number" bind:value={item.penalty}/></label><label><input type="checkbox" checked={!!item.heavy} onchange={e=>item.heavy=e.currentTarget.checked}/> Pesada</label>{/if}<label>Material<input bind:value={item.material}/></label><label class="wide">Descrição<textarea bind:value={item.description}></textarea></label><button class="danger" onclick={()=>removeEntry(equipment,item.id)}>Remover</button></div>{/if}</div>{/each}
            {/each}
            <div class="equipment-money"><label>TO<input type="number" min="0" value={coins.to} onchange={e=>setCoins('to',Number(e.currentTarget.value),e.currentTarget)}/></label><label>TS<input type="number" min="0" value={coins.ts} onchange={e=>setCoins('ts',Number(e.currentTarget.value),e.currentTarget)}/></label><label>TC<input type="number" min="0" value={coins.tc} onchange={e=>setCoins('tc',Number(e.currentTarget.value),e.currentTarget)}/></label></div><div class="equipment-totals"><span>Carga {carried} / {loadLimit} espaços {#if overloaded}· Sobrecarregado{/if}</span><strong>{armorPenalty} penalidade</strong></div></section>
          <section class="sheet-panel frame"><header><h2>Proficiências</h2><button onclick={()=>openEditor('proficiencies')} aria-label="Editar proficiências"><Icon name="tune" size={15}/></button></header><p class="proficiency-list">{proficiencies.join(' · ')}</p></section>
        </aside></div></div></main>
  {/if}
  {#if newDialog}<button class="modal-backdrop" in:fade={{duration:150}} out:fade={{duration:120}} aria-label="Fechar nova ficha" onclick={closeNewDialog}></button><div class="modal frame" in:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:200}} out:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:140}} role="dialog" aria-modal="true" aria-labelledby="new-sheet-title" tabindex="-1"><header><h2 id="new-sheet-title">Nova ficha</h2><button onclick={closeNewDialog} aria-label="Fechar"><Icon name="close"/></button></header><button class="creation-option" disabled><Icon name="guide" size={25}/><span><strong>Ficha guiada</strong><small>Disponível em uma próxima etapa.</small></span></button><button class="creation-option" onclick={createAdvanced}><Icon name="settings" size={25}/><span><strong>Criação avançada</strong><small>Comece com uma ficha completamente vazia.</small></span><Icon name="chevron"/></button></div>{/if}
  {#if editor}<button class="drawer-backdrop" in:fade={{duration:150}} out:fade={{duration:120}} aria-label="Fechar editor" onclick={closeEditor}></button><div class="drawer sheet-editor" in:fly={{x:prefersReducedMotion.current?0:24,duration:prefersReducedMotion.current?120:220}} out:fly={{x:prefersReducedMotion.current?0:24,duration:prefersReducedMotion.current?120:150}} role="dialog" aria-modal="true" tabindex="-1"><header><h2>{editor==='attributes'?'Ajustes de atributos':editor==='defense'?'Defesa e RD':editor==='movement'?'Movimento e tamanho':'Proficiências'}</h2><button onclick={closeEditor} aria-label="Fechar"><Icon name="close"/></button></header>
    {#if editor==='attributes'}<p>Ajustes temporários de −20 a +20. Não alteram PV/PM máximos.</p>{#each labels as label,index}<label>{label}<input type="number" min="-20" max="20" bind:value={temporaryDraft[index]}/></label>{/each}<div class="editor-actions"><button onclick={()=>temporaryDraft=[0,0,0,0,0,0]}>Zerar</button><button onclick={closeEditor}>Cancelar</button><button class="primary" onclick={()=>{temporaryAttributes=temporaryDraft.map(n=>Math.max(-20,Math.min(20,Math.trunc(Number(n)||0))));closeEditor();sheetDirty=true;}}>Salvar</button></div>{/if}
    {#if editor==='defense'}<p>Prévia: {defense} · 10 + atributo + armadura + escudo + poderes/efeitos + ajuste.</p><label>Base<input type="number" bind:value={defenseBase}/></label><label><input type="checkbox" bind:checked={defenseUsesAttribute}/> Usar atributo na Defesa</label><label>Atributo<select bind:value={defenseAttribute}>{#each labels as label,index}<option value={index}>{label}</option>{/each}</select></label><label>Ajuste manual<input type="number" bind:value={defenseManual}/></label><h3>Redução de dano</h3><label>RD geral<input type="number" bind:value={manualRd.Geral}/></label>{#each damageTypes as type}<label>RD {type}<input type="number" bind:value={manualRd[type]}/></label>{/each}<button class="primary" onclick={closeEditor}>Concluir</button>{/if}
    {#if editor==='movement'}<p>Deslocamento racial: {ancestryRule?.movement??9} m. Prévia atual: {movement} m.</p><label>Tamanho<select value={sizeOverride??''} onchange={e=>sizeOverride=e.currentTarget.value?e.currentTarget.value as Size:null}><option value="">Racial</option>{#each sizes as size}<option value={size}>{size}</option>{/each}</select></label><label>Deslocamento base (m)<input type="number" min="0" placeholder={String(ancestryRule?.movement??9)} value={movementBase??''} onchange={e=>movementBase=e.currentTarget.value===''?null:Number(e.currentTarget.value)}/></label>{#each ['Voo','Natação','Escalada','Escavação'] as mode}<label>{mode} (m)<input type="number" min="0" bind:value={otherMovement[mode]}/></label>{/each}<small>Modos raciais: {ancestry==='Sereia/Tritão'?'Natação 12 m':ancestry==='Sílfide'?'Voo 12 m (1 PM/rodada)':'nenhum adicional'}. Armadura/carga não reduzem o golem.</small><button class="primary" onclick={closeEditor}>Concluir</button>{/if}
    {#if editor==='proficiencies'}<p>{canEditProficiencies()?'Marque as proficiências da ficha.':'O mestre precisa autorizar a edição customizada nesta ficha.'}</p>{#each proficiencyOptions as option}<label><input type="checkbox" checked={proficiencies.includes(option)} disabled={!canEditProficiencies()} onchange={e=>updateProficiency(option,e.currentTarget.checked)}/>{option}</label>{/each}<label>Proficiência concedida por poder<select bind:value={proficiencyChoice} disabled={!canEditProficiencies()}>{#each proficiencyOptions as option}<option>{option}</option>{/each}</select></label><button class="primary" onclick={closeEditor}>Concluir</button>{/if}
  </div>{/if}
  {#if effectEditor}<button class="modal-backdrop" in:fade={{duration:150}} out:fade={{duration:120}} aria-label="Fechar efeito" onclick={closeEffectEditor}></button><div class="modal effect-modal frame" in:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:200}} out:fly={{y:prefersReducedMotion.current?0:8,duration:prefersReducedMotion.current?120:140}} role="dialog" aria-modal="true"><header><h2>Efeito personalizado</h2><button onclick={closeEffectEditor} aria-label="Fechar"><Icon name="close"/></button></header><p>Um bônus por efeito. Ativação cobra apenas os PM iniciais; manutenção é manual.</p><label>Nome<input bind:value={effectDraft.name}/></label><label>Descrição<textarea bind:value={effectDraft.description}></textarea></label><label>Descrição do tier único<input bind:value={effectDraft.tierDescription}/></label><label>Nível mínimo<input type="number" min="1" max="20" bind:value={effectDraft.minimumLevel}/></label><label>Custo inicial de PM<input type="number" min="0" bind:value={effectDraft.cost}/></label><label>Bônus<select bind:value={effectDraft.kind}>{#each ['Atributo','Defesa','Deslocamento','Deslocamento substituir','Perícia','Perícia todas','Dano de arma','Redução de dano','PV máximo','PM máximo'] as kind}<option>{kind}</option>{/each}</select></label>{#if effectDraft.kind==='Atributo'}<label>Atributo<select bind:value={effectDraft.attribute}>{#each labels as label,index}<option value={index}>{label}</option>{/each}</select></label>{/if}{#if effectDraft.kind==='Perícia'}<label>Perícia<select bind:value={effectDraft.skill}>{#each skills as skill}<option>{skill.name}</option>{/each}</select></label>{/if}<label>Valor<input type="number" bind:value={effectDraft.value}/></label><div class="editor-actions"><button onclick={closeEffectEditor}>Cancelar</button>{#if editingEffect!==null}<button class="danger" onclick={()=>{effects=effects.filter(e=>e.id!==editingEffect);closeEffectEditor();sheetDirty=true;}}>Remover</button>{/if}<button class="primary" onclick={saveEffect}>Salvar</button></div></div>{/if}
  {#if settingsOpen}<button class="drawer-backdrop" in:fade={{duration:150}} out:fade={{duration:120}} aria-label="Fechar configurações" onclick={closeSettings}></button><div class="drawer settings-drawer" in:fly={{x:prefersReducedMotion.current?0:24,duration:prefersReducedMotion.current?120:220}} out:fly={{x:prefersReducedMotion.current?0:24,duration:prefersReducedMotion.current?120:150}} role="dialog" aria-modal="true" aria-label="Configurações" tabindex="-1"><header><h2>Configurações</h2><button onclick={closeSettings} aria-label="Fechar"><Icon name="close"/></button></header><nav class="settings-tabs" aria-label="Seções das configurações"><button class:active={settingsTab==='geral'} onclick={()=>settingsTab='geral'}>Geral</button><button class:active={settingsTab==='aparencia'} onclick={()=>settingsTab='aparencia'}>Aparência</button></nav>{#if settingsTab==='geral'}<div class="settings-section"><label>Página inicial<select value={startPage} onchange={e=>setStartPage(e.currentTarget.value as Section)}><option value="resumo">Resumo</option><option value="mesas">Mesas</option><option value="fichas">Fichas</option><option value="livros">Livros</option></select><small>Área exibida ao abrir A Guilda VTT.</small></label><label class="settings-check"><input type="checkbox" checked={confirmLeave} onchange={e=>setConfirmLeave(e.currentTarget.checked)}/><span><strong>Confirmar ao sair da mesa</strong><small>Evita encerrar uma sessão por engano.</small></span></label></div>{:else}<div class="settings-section"><fieldset><legend>Tema visual</legend>{#each [['modern','Moderno','Escuro · cartões e cantos modernos'],['archaic','Arcaico','Cartografia da Guilda · mesma estrutura'],['nimb','Nimb','Claro · fantasia e vermelho']] as option}<label class="theme-option theme-style-option" class:selected={style===option[0]}><input type="radio" name="style" value={option[0]} checked={style===option[0]} onchange={()=>setStyle(option[0] as ThemeStyle)}/><span class={`theme-preview ${option[0]}`} aria-hidden="true"><i></i><i></i><i></i></span><span><strong>{option[1]}</strong><small>{option[2]}</small></span></label>{/each}</fieldset>{#if style==='archaic'}<fieldset><legend>Luminosidade do Arcaico</legend>{#each [['system','Sistema','Segue a preferência do Windows'],['light','Claro','Papel bege para ambientes iluminados'],['dark','Escuro','Preto para sessões com pouca luz']] as option}<label class="theme-option"><input type="radio" name="theme" value={option[0]} checked={themeChoice===option[0]} onchange={()=>setTheme(option[0] as ThemePreference)}/><span><strong>{option[1]}</strong><small>{option[2]}</small></span></label>{/each}</fieldset>{/if}</div>{/if}</div>{/if}
  {#if compendiumOpen && sheetOpen}<aside id="compendium-helper" class="compendium-helper" in:fly={{x:prefersReducedMotion.current?0:14,duration:prefersReducedMotion.current?120:180}} out:fly={{x:prefersReducedMotion.current?0:14,duration:prefersReducedMotion.current?120:140}} aria-label="Compêndio de consulta"><header><div><small>CONSULTA RÁPIDA</small><h2>Compêndio</h2></div><button class="helper-close" onclick={()=>compendiumOpen=false} aria-label="Fechar compêndio"><Icon name="close"/></button></header><div class="helper-controls"><input class="helper-search" type="search" bind:value={query} aria-label="Pesquisar no compêndio" placeholder="Buscar item, magia ou poder..."/><div class="helper-filters"><label>Tipo<select value={catalogGroup} onchange={e=>changeCatalogGroup(e.currentTarget.value as CatalogGroup|'Todos')}><option>Todos</option>{#each ['Armas','Armaduras','Escudos','Munições','Magias','Poderes'] as group}<option>{group}</option>{/each}</select></label>{#if catalogGroup==='Armas'||catalogGroup==='Armaduras'||catalogGroup==='Poderes'}<label>Categoria<select bind:value={categoryFilter}><option>Todas</option>{#each categories as category}<option>{category}</option>{/each}</select></label>{/if}{#if catalogGroup==='Magias'}<label>Círculo<select bind:value={circleFilter}><option>Todos</option>{#each [1,2,3,4,5] as circle}<option value={circle}>{circle}º</option>{/each}</select></label><label>Tradição<select bind:value={traditionFilter}><option>Todas</option><option>Arcana</option><option>Divina</option><option>Universal</option></select></label>{/if}</div><small class="helper-count">{filteredCompendium.length} {filteredCompendium.length===1?'resultado':'resultados'} · amostra local do Livro Básico</small></div><div class="helper-list">{#each filteredCompendium as item}<article draggable="true" ondragstart={e=>dragCatalogItem(item,e)}><div class="helper-item"><strong>{item.name}</strong><small>{item.group==='Magias'?item.summary:item.group==='Armas'?`${item.category} · ${item.summary}`:item.summary}</small><span>{item.detail}</span><em>{item.page}</em></div><div class="helper-actions">{#if item.group==='Armas'}<button onclick={()=>addCatalogItem(item)} aria-label={`Adicionar ${item.name} aos ataques`} title="Adicionar aos ataques"><Icon name="sword" size={15}/></button><button onclick={()=>addCatalogItem(item,true)} aria-label={`Adicionar ${item.name} aos equipamentos`} title="Adicionar aos equipamentos"><Icon name="bag" size={15}/></button>{:else}<button onclick={()=>addCatalogItem(item)} aria-label={`Adicionar ${item.name} à ficha`} title="Adicionar à ficha"><Icon name="plus" size={16}/></button>{/if}</div></article>{:else}<p class="helper-empty">Nenhum resultado para esses filtros.</p>{/each}</div><footer>Esta amostra não é exaustiva. Consulte o livro para as regras completas.</footer></aside>{/if}
</div>
